```cpp
#include "matplotlib-cpp/matplotlibcpp.h"
#include <vector>
#include <string>
#include <fstream>
#include <sstream>
#include <algorithm>

namespace plt = matplotlibcpp;

void plotCandlestick(const std::string& pair, const std::string& granularity) {
    std::string filename = utils::get_his_data_filename(pair, granularity);

    std::vector<std::string> time;
    std::vector<double> open, high, low, close;

    // Read data from file
    std::ifstream file(filename);
    std::string line;
    std::getline(file, line); // Skip header

    while (std::getline(file, line)) {
        std::istringstream iss(line);
        std::string t;
        double o, h, l, c;
        if (!(iss >> t >> o >> h >> l >> c)) { break; }
        time.push_back(t);
        open.push_back(o);
        high.push_back(h);
        low.push_back(l);
        close.push_back(c);
    }

    // Get last 100 data points
    int dataSize = std::min(100, static_cast<int>(time.size()));
    std::vector<std::string> plotTime(time.end() - dataSize, time.end());
    std::vector<double> plotOpen(open.end() - dataSize, open.end());
    std::vector<double> plotHigh(high.end() - dataSize, high.end());
    std::vector<double> plotLow(low.end() - dataSize, low.end());
    std::vector<double> plotClose(close.end() - dataSize, close.end());

    // Plot candlestick
    plt::figure_size(1200, 800);
    plt::title(pair + " - " + granularity);
    plt::candlestick(plotTime, plotOpen, plotHigh, plotLow, plotClose);
    plt::xlabel("Time");
    plt::ylabel("Price");
    plt::show();
}

// In your fetchInstruments function or wherever appropriate
void fetchInstruments() {
    // ... existing code ...

    // Example usage
    plotCandlestick("EUR_USD", "H1");

    // ... rest of the function ...
}
```

