#include "matplotlibcpp.h"
namespace plt = matplotlibcpp;

// Replace utils::get_his_data_filename with a direct function
std::string get_his_data_filename(const std::string& pair, const std::string& granularity) {
    return pair + "_" + granularity + "_data.csv";
}

void plotCandlestick(const std::string& pair, const std::string& granularity) {
    // ... (keep the data reading part as is)

    // Create candlestick plot manually
    plt::figure_size(1200, 800);
    plt::title(pair + " - " + granularity);

    for (size_t i = 0; i < plotTime.size(); ++i) {
        std::vector<double> x{i, i};
        std::vector<double> prices{plotLow[i], plotHigh[i]};
        plt::plot(x, prices, "b-"); // Draw the wick

        if (plotClose[i] > plotOpen[i]) {
            plt::fill_between(std::vector<double>{i-0.4, i+0.4}, 
                              std::vector<double>{plotOpen[i], plotOpen[i]},
                              std::vector<double>{plotClose[i], plotClose[i]}, "g");
        } else {
            plt::fill_between(std::vector<double>{i-0.4, i+0.4}, 
                              std::vector<double>{plotOpen[i], plotOpen[i]},
                              std::vector<double>{plotClose[i], plotClose[i]}, "r");
        }
    }

    plt::xlabel("Time");
    plt::ylabel("Price");
    plt::show();
}
