        open.push_back(o);
        high.push_back(h);
        low.push_back(l);
        close.push_back(c);
    }

    // Get last 100 data points
    int dataSize = std::min(100, static_cast<int>(time.size()));
    std::vector<std::string> plotTime(time.end() - dataSize, time.end());
    std::vector<double> plotOpen(open.end() - dataSize, open.end());
    std::vector<double> plotHigh(high.end() - dataSize, high.end());
    std::vector<double> plotLow(low.end() - dataSize, low.end());
    std::vector<double> plotClose(close.end() - dataSize, close.end());

    // Calculate MA_8
    std::vector<double> MA_8(plotClose.size());
    for (size_t i = 7; i < plotClose.size(); ++i) {
        MA_8[i] = std::accumulate(plotClose.begin() + i - 7, plotClose.begin() + i + 1, 0.0) / 8.0;
    }

    // Create candlestick plot manually
    plt::figure_size(1000, 300);
    plt::title(pair + " - " + granularity);

    // Set plot limits
    double x_min = -1, x_max = plotTime.size();
    double y_min = *std::min_element(plotLow.begin(), plotLow.end());
    double y_max = *std::max_element(plotHigh.begin(), plotHigh.end());
    plt::xlim(x_min, x_max);
    plt::ylim(y_min, y_max);

    // Create background rectangle
    plt::plot(std::vector<double>{x_min, x_max, x_max, x_min, x_min}, 
              std::vector<double>{y_min, y_min, y_max, y_max, y_min}, 
              "#1e1e1e");

    // Draw grid
    plt::grid(true);

    // Draw candlesticks
    for (size_t i = 0; i < plotTime.size(); ++i) {
        std::vector<double> x{static_cast<double>(i), static_cast<double>(i)};
        std::vector<double> prices{plotLow[i], plotHigh[i]};

        if (plotClose[i] > plotOpen[i]) {
            plt::plot(x, prices, "#2EC886");
            plt::plot(std::vector<double>{i-0.4, i-0.4, i+0.4, i+0.4}, 
                      std::vector<double>{plotOpen[i], plotClose[i], plotClose[i], plotOpen[i]}, 
                      "#24A06B");
        } else {
            plt::plot(x, prices, "#FF3A4C");
            plt::plot(std::vector<double>{i-0.4, i-0.4, i+0.4, i+0.4}, 
                      std::vector<double>{plotOpen[i], plotClose[i], plotClose[i], plotOpen[i]}, 
                      "#CC2E3C");
        }
    }

    // Add MA_8 line
    std::vector<double> x_ma(plotTime.size());
    std::iota(x_ma.begin(), x_ma.end(), 0);
    plt::plot(x_ma, MA_8, "#027FC3");

    plt::xlabel("Time");
    plt::ylabel("Price");
    plt::tight_layout();
    plt::show();
}
```

This code incorporates all the changes we've discussed, including the candlestick plotting, background color, grid, and the addition of the MA_8 line, while ensuring compatibility with the matplotlib-cpp library.

Certainly. Here's the complete code for TradingStrategy.cpp with all the suggested changes implemented:

```cpp
#include "TradingStrategy.h"
#include "TechnicalIndicators.h"
#include <algorithm>
#include <numeric>
#include <stdexcept>
#include <cmath>

TradingStrategy::TradingStrategy(int smaPeriod, double stopLossMultiplier, double riskPercentage)
    : smaPeriod(smaPeriod), stopLossMultiplier(stopLossMultiplier), riskPercentage(riskPercentage) {
    if (stopLossMultiplier <= 0 || riskPercentage <= 0 || riskPercentage > 100) {
        throw std::invalid_argument("Invalid stopLossMultiplier or riskPercentage");
    }
}

std::vector<Signal> TradingStrategy::calculateSignals(const std::vector<double>& priceData) {
    if (priceData.size() < static_cast<size_t>(smaPeriod)) {
        throw std::runtime_error("Insufficient data for SMA calculation");
    }

    std::vector<double> sma = TechnicalIndicators::calculateSMA(priceData, smaPeriod);
    std::vector<double> atr = calculateATR(priceData, 14);  // 14-period ATR
    std::vector<Signal> signals;

    for (size_t i = smaPeriod; i < priceData.size(); ++i) {
        Signal signal;
        signal.time = i;
        signal.price = priceData[i];

        if (priceData[i] > sma[i - smaPeriod] && priceData[i - 1] <= sma[i - smaPeriod - 1]) {
            signal.type = SignalType::BUY;
            signal.stopLoss = priceData[i] - stopLossMultiplier * atr[i];
        } else if (priceData[i] < sma[i - smaPeriod] && priceData[i - 1] >= sma[i - smaPeriod - 1]) {
            signal.type = SignalType::SELL;
            signal.stopLoss = priceData[i] + stopLossMultiplier * atr[i];
        } else {
            signal.type = SignalType::NONE;
        }

        if (signal.type != SignalType::NONE) {
            signal.positionSize = calculatePositionSize(signal.price, signal.stopLoss);
            signals.push_back(signal);
        }
    }

    return signals;
}

std::vector<double> TradingStrategy::calculateATR(const std::vector<double>& priceData, int period) {
    std::vector<double> trueRanges;
    for (size_t i = 1; i < priceData.size(); ++i) {
        double highLow = std::abs(priceData[i] - priceData[i-1]);
        trueRanges.push_back(highLow);
    }

    return TechnicalIndicators::calculateSMA(trueRanges, period);
}

double TradingStrategy::calculatePositionSize(double currentPrice, double stopLoss) const {
    double riskAmount = accountBalance * (riskPercentage / 100.0);
    double riskPerShare = std::abs(currentPrice - stopLoss);
    return std::floor(riskAmount / riskPerShare);
}

void TradingStrategy::setAccountBalance(double balance) {
    if (balance <= 0) {
        throw std::invalid_argument("Account balance must be positive");
    }
    accountBalance = balance;
}

void TradingStrategy::backtest(const std::vector<double>& priceData) {
    std::vector<Signal> signals = calculateSignals(priceData);
    double totalProfit = 0.0;
    int winningTrades = 0;
    int losingTrades = 0;

    for (size_t i = 0; i < signals.size() - 1; ++i) {
        double entryPrice = signals[i].price;
        double exitPrice = signals[i + 1].price;
        double profit = (signals[i].type == SignalType::BUY) ? 
                        (exitPrice - entryPrice) * signals[i].positionSize :
                        (entryPrice - exitPrice) * signals[i].positionSize;

        totalProfit += profit;
        if (profit > 0) ++winningTrades;
        else ++losingTrades;

        // Log trade details
        std::cout << "Trade " << i + 1 << ": " 
                  << (signals[i].type == SignalType::BUY ? "BUY" : "SELL")
                  << " Entry: " << entryPrice
                  << " Exit: " << exitPrice
                  << " Profit: " << profit << std::endl;
    }

    std::cout << "Total Profit: " << totalProfit << std::endl;
    std::cout << "Win Rate: " << (static_cast<double>(winningTrades) / (winningTrades + losingTrades)) * 100 << "%" << std::endl;
}
```

This updated code incorporates all the suggested changes, including improved error handling, use of TechnicalIndicators for SMA calculation, better memory management, input validation, code organization, and the addition of a backtesting function.
